VALUES (NULL, NULL, 8948, 'Routine', 'Routine', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coay6e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6e4t.jpg', 'Routine is a First Person Sci-Fi Horror title set on an abandoned Lunar base designed around an 80’s vision of the future. Curious exploration turns into a need for survival when a lunar base goes completely quiet. Searching for answers puts you face to face with an enemy who is certain the main threat is you. Discoveries lead to deeper unknowns and the only way to go is forward.', 'https://www.igdb.com/games/routine', '["Xbox Series X|S", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.8, 0, 1.03, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
