VALUES (NULL, NULL, 2279, 'Zombi', 'Zombi', 'game', 1986, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dip.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/syravp1xacekonhrrbue.jpg', 'Zombi is an icon-driven action-adventure video game and Ubisoft''s first publication. It is a first-person action adventure with four protagonists exploring a zombie-filled shopping mall. If a character''s health is depleted, he turns into a zombie, which then roams the room they died in. Zombies can be killed either by numerous body shots, or a single shot to the head. Characters are named after the creators of the game.', 'https://www.igdb.com/games/zombi', '["Commodore C64/128/MAX", "ZX Spectrum", "Atari ST/STE", "DOS", "Amiga", "Amstrad CPC"]', NULL, 6.8, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
