VALUES (NULL, NULL, 327, 'Age of Empires II: The Age of Kings', 'Age of Empires II: The Age of Kings', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co55xo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7qh.jpg', 'Take control of a powerful civilization. Lead them through 1000 years of the Middle Ages to riches and greatness. Will you Intimidate the world into following you by using military force? Rule the world with honor and nobility by using commerce and diplomacy? Or Underhandedly seize power through conspiracy, deception and regicide? There are many paths to power, there can only be one ruler!', 'https://www.igdb.com/games/age-of-empires-ii-the-age-of-kings', '["PC (Microsoft Windows)", "Mac", "Dreamcast", "PlayStation 2"]', NULL, 8.3, 0, 1.25, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
