VALUES (NULL, NULL, 324, 'Age of Mythology', 'Age of Mythology', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co907c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7sb.jpg', 'Age of Mythology is a real-time strategy game developed by Ensemble Studios and published by Microsoft Game Studios. Drawing inspiration from Greek, Egyptian, and Norse mythology rather than historical events, it diverges from the Age of Empires series while sharing familiar gameplay elements. The campaign follows Arkantos, an Atlantean admiral embarking on a journey through the lands of the game''s three cultures, hunting for a cyclops who is in league with Poseidon against Atlantis.', 'https://www.igdb.com/games/age-of-mythology', '["PC (Microsoft Windows)", "Mac"]', NULL, 7.9, 0, 1.05, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
