VALUES (NULL, NULL, 10032, 'Ancestors: The Humankind Odyssey', 'Ancestors: The Humankind Odyssey', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rg8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6c9.jpg', 'Ancestors: The Humankind Odyssey is a single-player survival game played from a third-person view and set in an open world. Players control a member of a hominid clan and manage its needs by eating, drinking, and sleeping while facing predators and other dangers in the wild. Exploring new places and being hunted can trigger a state of fear, which is offset by rewarding actions such as crafting tools and making discoveries. As the clan learns and grows, players unlock new skills through a neural development system and can switch between clan members, passing acquired abilities to future generations. The game has no structured narrative campaign and instead lets players shape their own experience.', 'https://www.igdb.com/games/ancestors-the-humankind-odyssey', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.8, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
