VALUES (NULL, NULL, 102163, 'Dawn of Man', 'Dawn of Man', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qv9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6iw.jpg', 'Command a settlement of ancient humans, guide them through the ages in their struggle for survival. Hunt, gather, craft tools, fight, research new techs and face the challenges the environment will throw at you.', 'https://www.igdb.com/games/dawn-of-man', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 7.1, 0, 1.04, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
