VALUES (NULL, NULL, 5410, 'Pitfall: The Mayan Adventure', 'Pitfall: The Mayan Adventure', 'game', 1994, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fsd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s4izqtizj7xaewrbo1s9.jpg', 'Pitfall: The Mayan Adventure is a side-scrolling action game where players assume the role of adventurer Pitfall Harry Jr. as he searches for his father, Pitfall Harry. The game features various environments such as Mayan jungles, waterfalls, and deserted mines. Players can bungee jump and boomerang their way through 13 levels.', 'https://www.igdb.com/games/pitfall-the-mayan-adventure', '["Super Nintendo Entertainment System", "Sega 32X", "Wii", "Sega Mega Drive/Genesis", "PC (Microsoft Windows)", "Atari Jaguar", "Sega CD", "Game Boy Advance"]', NULL, 6.2, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
