VALUES (NULL, NULL, 272600, 'Soulmask', 'Soulmask', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobwop.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2l2d.jpg', 'Soulmask is a sandbox game that prioritizes an authentic survival experience. As the "last one" blessed with the mysterious mask, players will grapple for survival in a primitive land steeped in mysterious faiths, carving out a path to ascendance. Start from nothing, explore, build, recruit tribesmen to fortify your clan, and ultimately unravel the mysterious truths hidden behind the civilizations of this world.', 'https://www.igdb.com/games/soulmask', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
