VALUES (NULL, NULL, 253442, 'Ecumene Aztec', 'Ecumene Aztec', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mkw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2cvg.jpg', 'The Great Tenochtitlan is on fire. Now that the war has broken out, I must choose whether to join our compatriots to repel the invader, or to join the newcomers who want to liberate us from the priests sacrificing our own brothers and children.', 'https://www.igdb.com/games/ecumene-aztec', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
