VALUES (NULL, NULL, 244040, 'Bellwright', 'Bellwright', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coab5l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2k7c.jpg', 'Establish and expand your own settlements, liberate the land and assist its villagers, and recruit others to your cause while learning more about a life you had to leave behind. Command your forces, prove your valor through combat, and cement yourself as the hero of your people.', 'https://www.igdb.com/games/bellwright', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.3, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
