VALUES (NULL, NULL, 6258, 'The Guild 2', 'The Guild 2', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qsj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1741.jpg', 'The Guild 2 is the shining successor of the ultra successful medieval life sim, Europe 1400. The Guild 2 is a unique mixture of RPG and life simulation in an immersive middle ages scenario. The player and his party become part of history and can even change it in real-time.

Go back to the dark middle ages and found a new dynasty! Take care of yourself, because your opponents never sleep! Marry a beautiful wife and make new friends... control your life! Hand down your skills and your descendants will greatly appreciate it!', 'https://www.igdb.com/games/the-guild-2', '["Linux", "PC (Microsoft Windows)"]', NULL, 7.4, 0, 1.11, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
