VALUES (NULL, NULL, 248, 'Populous', 'Populous', 'game', 1989, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2jjf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23bz.jpg', 'Populous is a real-time strategy game where the player takes the role of a deity influencing the development of civilizations. You shape terrain, guide followers, and use natural disasters like floods, volcanoes, and earthquakes to influence or eliminate opposing tribes. The game features an isometric perspective and includes 500 levels (worlds), each with different challenges. Originally developed by Bullfrog and designed by Peter Molyneux, it is considered one of the earliest examples of the god-game genre.', 'https://www.igdb.com/games/populous', '["Acorn Archimedes", "PC-9800 Series", "Sharp X68000", "Super Nintendo Entertainment System", "Sega Mega Drive/Genesis", "Atari ST/STE", "PC (Microsoft Windows)", "TurboGrafx-16/PC Engine", "Mac", "DOS", "Amiga", "Sega Master System/Mark III"]', NULL, 7.4, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
