VALUES (NULL, NULL, 143610, 'Triangle Strategy', 'Triangle Strategy', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8wc0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar14jq.jpg', 'Three nations battle for control of the dwindling resources of salt and iron in this HD-2D adventure tactical RPG. Featuring deep gameplay full of choices and consequences, strategically survey the battlefield to gain the upper hand.', 'https://www.igdb.com/games/triangle-strategy', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, 8.6, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
