VALUES (NULL, NULL, 252830, 'Microsoft Flight Simulator 2024', 'Microsoft Flight Simulator 2024', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91qm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6i46.jpg', 'Pursue your dream of an aviation career with Microsoft Flight Simulator 2024. This brand-new simulator is designed to take advantage of the latest technologies in simulation, cloud, machine learning, graphics and gaming to create the most sophisticated, immersive and awe-inspiring flight simulator of all time. To achieve this unprecedented level of accuracy, Microsoft Flight Simulator 2024 is powered by the significantly evolved Asobo Studio engine.', 'https://www.igdb.com/games/microsoft-flight-simulator-2024', '["Xbox Series X|S", "PlayStation VR2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 8.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
