VALUES (NULL, NULL, 7333, 'Crackdown 3', 'Crackdown 3', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2388.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4xp.jpg', 'Stop crime as a super-powered Agent of justice in Crackdown 3''s hyper-powered sandbox of mayhem and destruction. Explore the heights of a futuristic city, race through the streets in a transforming vehicle, and use your powerful abilities to stop a ruthless criminal empire. Developed by original creator Dave Jones, Crackdown 3 delivers cooperative mayhem and an all-new multiplayer mode where destruction is your ultimate weapon.', 'https://www.igdb.com/games/crackdown-3', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 6.3, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
