VALUES (NULL, NULL, 234256, 'The Crew: Motorfest', 'The Crew: Motorfest', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6pe2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar23rz.jpg', 'The Crew Motorfest is an open-world racing game set on scaled-down versions of the Hawaiian islands of Oahu and Maui. The third entry in The Crew series, it is structured around a festival theme with "Playlists" consisting of staged races, side activities, and challenges built around topics like specific car brands or motorsport disciplines. Players can control cars, boats, and planes across the open world, and multiplayer modes include the Grand Race and Demolition Royale. The game originally started development as DLC for The Crew 2 before becoming a standalone title, and draws comparisons to the Forza Horizon series for its festival-based structure.', 'https://www.igdb.com/games/the-crew-motorfest', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 8.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
