VALUES (NULL, NULL, 11235, 'Future Cop: LAPD', 'Future Cop: LAPD', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2429.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kowlqmibawtyeubjwuzk.jpg', 'Crime War is a story mode, following a day in the life of an LAPD X1-Alpha pilot. The story events range from rogue lunatics arming observatories with weapons, to a malfunctioning supercomputer. Players begin in a futuristic Griffith Park, but as they advance through the game they may unlock areas such as Venice Beach, LAX and Long Beach.', 'https://www.igdb.com/games/future-cop-lapd', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "PlayStation", "PlayStation Portable"]', NULL, 7.1, 0, 9.53, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
