VALUES (NULL, NULL, 2174, 'Sonic & All-Stars Racing Transformed', 'Sonic & All-Stars Racing Transformed', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1zvw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4kr6.jpg', 'Race as Sonic and a host of legendary All-Stars and prepare to transform! Speed across land, sea and air in a high velocity battle to the finish line, as your amazing transformable vehicle changes from car to boat to plane mid-race. Racing on mobile will never be the same again!', 'https://www.igdb.com/games/sonic-all-stars-racing-transformed', '["PlayStation 3", "Android", "iOS", "Wii U", "PlayStation Vita", "Xbox 360"]', NULL, 8.0, 0, 9.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
