VALUES (NULL, NULL, 9681, 'Thexder', 'Thexder', 'game', 1985, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2w8h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3wgu.jpg', 'Thexder is a robot capable of transforming into a jet whose job is to destroy the central computer to save the planet.15 stages are waiting you for in this shooting game.', 'https://www.igdb.com/games/thexder', '["Apple IIGS", "PC-9800 Series", "PC-8800 Series", "Sharp X1", "TRS-80 Color Computer", "Mac", "DOS", "Amiga", "Apple II", "TRS-80", "Family Computer", "Sharp MZ-2200", "FM-7", "Nintendo Entertainment System", "MSX"]', NULL, 6.4, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
