VALUES (NULL, NULL, 188555, 'Blood West', 'Blood West', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7plb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2qam.jpg', 'Blood West is an immersive stealth shooter taking place in a nightmare version of a classic wild west setting. The player takes on the role of an outlawed gunslinger brought back to live by strange native spirits to find the root of a curse that has befallen the land. They will explore the dangerous frontier, gather supplies, expand their arsenal, and gain experience to unlock special traits, to best the many monsters and face off with challenging bosses.', 'https://www.igdb.com/games/blood-west', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.3, 0, 10.52, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
