VALUES (NULL, NULL, 1677, 'Wild Arms', 'Wild Arms', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1war.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3scm.jpg', 'Wild Arms is a Western-themed role-playing video game developed by Japanese software company Media.Vision. Originally released in Japan in 1996 for the Sony PlayStation video game console, it was later translated and released in North America in 1997 and Europe in 1998 by Sony Computer Entertainment. It is noteworthy for not only being one of the first role-playing video games on the PlayStation, but also one of the few to feature a Western American setting and motif. The game features 2D computer graphics for normal gameplay, while battle sequences are rendered in 3D.', 'https://www.igdb.com/games/wild-arms', '["PlayStation 3", "Android", "PlayStation", "PlayStation Portable"]', NULL, 8.0, 0, 10.03, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
