VALUES (NULL, NULL, 408607, 'Guns of Eschaton', 'Guns of Eschaton', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocrqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6a5a.jpg', 'The worlds first soulslike FPS pulls you into an apocalyptic Western by the legendary Viktor Antonov: a land of dust, blood, and horror. Study your enemies, count your bullets, forge your own style with gunpowder and prayers. Solo or in co-opgo West, gunslinger, go West and die with the country!', 'https://www.igdb.com/games/guns-of-eschaton', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 9.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
