VALUES (NULL, NULL, 348263, 'Far Far West', 'Far Far West', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaqrh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3pac.jpg', 'Yee-haw, Cowboys! Team up in this chaotic 4-player co-op shooter. Journey to the Far Far West to blast monsters, sling spells, complete missions, and collect bounties. Work as a team to get in, get paid and get out (mostly) alive.', 'https://www.igdb.com/games/far-far-west', '["PC (Microsoft Windows)"]', NULL, 9.3, 0, 9.15, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
