VALUES (NULL, NULL, 473, 'Battlefield: Bad Company', 'Battlefield: Bad Company', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xbe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8kk.jpg', 'Set in the near future, the Battlefield: Bad Company single-player campaign drops gamers behind enemy lines as part of a squad of four soldiers - risking it all to go AWOL on a personal quest. Featuring a dramatic storyline flavoured with attitude, Battlefield: Bad Company leads gamers far from the traditional frontlines on a wild ride with a group of renegade soldiers who decide that sometimes the gratitude of a nation just isn’t enough.

Battlefield: Bad Company is the first game built from the ground up for next-generation consoles using DICE’s bleeding-edge Frostbite game engine, delivering unrivalled graphics, effects and gameplay. Join Bad Company now.', 'https://www.igdb.com/games/battlefield-bad-company', '["PlayStation 3", "Xbox 360"]', NULL, 8.2, 0, 9.52, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
