VALUES (NULL, NULL, 3146, 'Plants vs. Zombies: Garden Warfare', 'Plants vs. Zombies: Garden Warfare', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qyz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8c1.jpg', 'Plants vs. Zombies is digging into the trenches with an explosive new 3D experience. Blast zombies, plants, and new characters with inventive weapons across a mine-blowing PvZ world. Take on Co-Op and Multiplayer action with your friends and sow the seeds of victory!', 'https://www.igdb.com/games/plants-vs-zombies-garden-warfare-2e561d33-2b92-408a-92f2-ec79ddcc6c2b', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.4, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
