VALUES (NULL, NULL, 17832, 'Don''t Starve Together', 'Don''t Starve Together', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaqp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5m2.jpg', 'Fight, Farm, Build and Explore Together in the standalone multiplayer expansion to the uncompromising wilderness survival game, Don''t Starve. Discover and explore a massive procedurally generated and biome-rich world with countless resources and threats. Whether you stick to the surface world, go spelunking in the caves, dive deeper into the Ancient Archive, or set sail for the Lunar islands, it will be a long time before you run out of things to do.', 'https://www.igdb.com/games/dont-starve-together', '["Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Nintendo Switch"]', NULL, 7.6, 0, 1.06200000000000009e+01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
