VALUES (NULL, NULL, 13226, 'Keep Talking and Nobody Explodes', 'Keep Talking and Nobody Explodes', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/aykvlxlmax2rcvljwkqn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardf9.jpg', 'One player is trapped in a virtual room with a ticking time bomb they must defuse. The other players are the “Experts” who must give the instructions to defuse the bomb by deciphering the information found in the bomb defusal manual. But there’s a catch: the experts can’t see the bomb, so everyone will need to talk it out – fast!', 'https://www.igdb.com/games/keep-talking-and-nobody-explodes', '["Meta Quest 2", "Windows Mixed Reality", "PlayStation 4", "Linux", "Gear VR", "PlayStation VR", "Android", "PC (Microsoft Windows)", "iOS", "SteamVR", "Mac", "Oculus Rift", "Daydream", "Xbox One", "Nintendo Switch", "Oculus Quest"]', NULL, 8.4, 0, 10.52, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
