VALUES (NULL, NULL, 346940, 'Roadside Research', 'Roadside Research', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavec.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar480w.jpg', 'Roadside Research is a 1 to 4 player co-op gas station simulator. Except you’re aliens. And undercover. Do very human things like restocking shelves while preparing for the invasion. Just don’t get caught.', 'https://www.igdb.com/games/roadside-research', '["Xbox Series X|S", "PC (Microsoft Windows)"]', NULL, 7.0, 0, 8.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
