VALUES (NULL, NULL, 34939, 'Eco', 'Eco', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1wlv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armtf.jpg', 'Enter the world of Eco, a fully simulated ecosystem bustling with thousands of growing plants and animals living their lives. Build, harvest, and take resources from an environment where your every action affects the world around you. An imminent meteor strike threatens global destruction. Can you save the world without destroying it in the process?', 'https://www.igdb.com/games/eco--1', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.7, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
