VALUES (NULL, NULL, 36897, 'A Way Out', 'A Way Out', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vca.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/i07d0geqvdjz5tkaqnvf.jpg', 'A Way Out is a cooperative action-adventure game designed exclusively for two-player split-screen play, either locally or online. Each player controls one of two protagonists, Leo and Vincent, who form a reluctant partnership to break out of prison. Gameplay involves stealth, combat, driving, and environmental puzzle-solving, with both characters taking different cooperative roles in each situation. The game features a branching narrative that unfolds simultaneously for both players through its split-screen presentation.', 'https://www.igdb.com/games/a-way-out', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.6, 0, 10.58, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
