VALUES (NULL, NULL, 348306, 'Stars of Icarus', 'Stars of Icarus', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9xxm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ovw.jpg', 'Assemble your crew and take to the stars in a team-based PvP dogfight. Enter the forgotten arenas of space, master your ship''s loadout and strategize with the rest of your ragtag squadron. Victory or death, together.', 'https://www.igdb.com/games/stars-of-icarus', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 9.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
