VALUES (NULL, NULL, 336733, 'Wildgate', 'Wildgate', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9kqs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3daf.jpg', 'Wildgate is a PVP multiplayer shooter that blends tactical ship-to-ship combat with fast-paced first-person action. Evade deadly environmental hazards, search for powerful weapons and ship upgrades, and be the first crew to escape with the Artifact... or the last crew left flying.', 'https://www.igdb.com/games/wildgate', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.1, 0, 8.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
