VALUES (NULL, NULL, 18433, 'Overcooked!', 'Overcooked!', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co262g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4tv9.jpg', 'Overcooked! is a co-op cooking game for 1-4 players. Working as a team, you and your fellow chefs must prepare, cook and serve up a variety of tasty orders before the baying customers storm out. Take part in an epic journey across the Onion Kingdom and tackle an increasingly challenging and bizarre gauntlet of kitchens which will push your skills of co-operation and co-ordination to the very limits.', 'https://www.igdb.com/games/overcooked', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 10.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
