VALUES (NULL, NULL, 113078, 'Conduct Together!', 'Conduct Together!', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ps8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/araiu.jpg', 'Conduct TOGETHER! is an addictive game of explosive railway action that will challenge your inner conductor.

Conduct everything yourself or hand a Joy-Con controller to a friend for a hectic teamwork of commanding trains, switching tracks and avoiding collisions in increasingly challenging action-puzzles. Play with up to 4 friends for the ultimate party game!', 'https://www.igdb.com/games/conduct-together', '["Nintendo Switch"]', NULL, NULL, 0, 9.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
