VALUES (NULL, NULL, 125286, 'The Stretchers', 'The Stretchers', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xjj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara4z.jpg', 'The world has a bad case of the Dizzies - residents dizzied by Captain Brains - and only you can rescue them! Work with a friend in co-op or skillfully control two medics on your own to overcome the physics-based puzzles of each madcap mission. Either way, how you go about it is totally up to you, whether you work together to transport many Dizzies at once on a stretcher or work in parallel by splitting up dragging the Dizzies to the ambulance one by one. As you play and replay missions, you''ll complete bonus objectives and uncover hidden collectibles with hilarious results!', 'https://www.igdb.com/games/the-stretchers', '["Nintendo Switch"]', NULL, 8.1, 0, 9.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
