VALUES (NULL, NULL, 96322, 'Catastronauts', 'Catastronauts', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co268b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arabl.jpg', 'Can you deal with unrelenting disaster and hold your ship together long enough to destroy the enemy invaders? Repair systems, extinguish fires, arm the torpedoes, avoid deadly solar flares, destroy your friends and clone them back again; it''s all in the life of a Catastronaut!', 'https://www.igdb.com/games/catastronauts', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 6.0, 0, 9.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
