VALUES (NULL, NULL, 8739, 'Monaco: What''s Yours Is Mine', 'Monaco: What''s Yours Is Mine', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2h9p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjxl.jpg', 'Monaco: What''s Yours Is Mine (or simply Monaco'') is a video game made by indie developers at Pocketwatch Games. They are best known for winning the 2010 IGF Award in 2010 for their work on Monaco. The game was released for Windows on April 24, 2013, via Steam, and will be released for the Mac and XBLA platforms in 2013.', 'https://www.igdb.com/games/monaco-whats-yours-is-mine', '["Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Nintendo Switch"]', NULL, 7.7, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
