VALUES (NULL, NULL, 14465, 'Clandestine', 'Clandestine', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30en.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vo1dfvnqc0jhz43ys7us.jpg', 'Clandestine is a 2-player or singleplayer stealth/hacking game set in 1996. Asymmetrical co-op allows one player to take the role of the spy while a friend provides overwatch and assistance as the hacker, and unravel a post-Cold War espionage conspiracy.', 'https://www.igdb.com/games/clandestine', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
