VALUES (NULL, NULL, 375783, 'FNAF Online Multiplayer', 'FNAF Online Multiplayer', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobueg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5mes.jpg', 'An online multiplayer fangame of Five Nights at Freddy’s 1 where 3-5 players each occupy their own office and must collaborate via in-game voice chat to survive the night. One player can also assume the role of the Purple Guy, controlling animatronics to eliminate the others before 6AM. Currently in alpha, available for Windows via GameJolt and Itch.', 'https://www.igdb.com/games/fnaf-online-multiplayer', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 6.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
