VALUES (NULL, NULL, 77550, 'Death Coming', 'Death Coming', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/beeubzulgbrnw3irctqh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard82.jpg', 'Death Coming is a non-linear puzzle game where you must harvest human souls ‘Final Destination’ style. However, pesky mortals are not your only problem, as the Agents of Light will do everything they can to stop you.', 'https://www.igdb.com/games/death-coming', '["PlayStation 4", "PC (Microsoft Windows)", "Nintendo Switch"]', NULL, 7.0, 0, 9.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
