VALUES (NULL, NULL, 337712, 'RuneScape: Dragonwilds', 'RuneScape: Dragonwilds', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocaxf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar65bx.jpg', 'On RuneScape’s forgotten continent of Ashenfall, dragons have awoken. Gather, build, skill and craft to survive in this co-operative (1-4) survival crafting game. Only by mastering survival and uncovering ancient secrets can they hope to slay the Dragon Queen—alone or with allies.', 'https://www.igdb.com/games/runescape-dragonwilds', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.0, 0, 8.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
