VALUES (NULL, NULL, 252853, 'Citizen Sleeper 2: Starward Vector', 'Citizen Sleeper 2: Starward Vector', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hpi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar61mz.jpg', 'Citizen Sleeper 2: Starward Vector is a narrative-driven science-fiction RPG in which players take on the role of a Sleeper, an artificial human. Using a tabletop-inspired dice system, players manage resources, make difficult choices, and build relationships while seeking a new life among the settlements of the Starward Belt. Expanding on the original game, the sequel introduces a customizable ship, recruitable crew members, and high-risk contracts that require planning and adaptation. Player choices, character classes, and skill-based interactions shape both the story and the path forward.', 'https://www.igdb.com/games/citizen-sleeper-2-starward-vector', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Nintendo Switch"]', NULL, 8.0, 0, 9.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
