VALUES (NULL, NULL, 3247, 'Sunset Overdrive', 'Sunset Overdrive', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20td.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar56r3.jpg', 'The city’s overrun with mutants. Problem? Not for you. Sunset Overdrive is an open-world playground of post-apocalyptic possibilities. Vault, grind & wall-run while using a deadly & unconventional arsenal. With hyper-agility, unique weapons, & customizable abilities, it rewrites the rules of shooters while delivering an irreverent adventure.', 'https://www.igdb.com/games/sunset-overdrive', '["PC (Microsoft Windows)", "Xbox One"]', NULL, 8.0, 0, 10.05, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
