VALUES (NULL, NULL, 138933, 'Five Nights at Freddy''s: Security Breach', 'Five Nights at Freddy''s: Security Breach', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4aro.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21w4.jpg', 'Five Nights at Freddy’s: Security Breach is the latest installment of the family-friendly horror games loved by millions of players from all over the globe. Play as Gregory, a young boy trapped overnight in Freddy Fazbear''s Mega Pizzaplex. With the help of Freddy Fazbear himself, Gregory must survive the near-unstoppable hunt of reimagined Five Nights at Freddy’s characters, as well as new, horrific threats.', 'https://www.igdb.com/games/five-nights-at-freddys-security-breach', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 5.9, 0, 9.05, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
