VALUES (NULL, NULL, 115843, 'Unpacking', 'Unpacking', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1t45.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8zs.jpg', 'Unpacking is a zen puzzle game about the familiar experience of pulling possessions out of boxes and fitting them into a new home. Part block-fitting puzzle, part home decoration, you are invited to create a satisfying living space while learning clues about the life you’re unpacking.

Over the course of eight house moves, you are given a chance to experience a sense of intimacy with a character you never see and a story you’re never told.', 'https://www.igdb.com/games/unpacking', '["Xbox Series X|S", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
