VALUES (NULL, NULL, 204623, 'Pentiment', 'Pentiment', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v1e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1oje.jpg', 'A 16th-century narrative adventure set in Upper Bavaria, following Andreas Maler, a journeyman artist working in the bygone scriptorium of Kiersau Abbey during a time of great social unrest. While finishing his masterpiece, Andreas inadvertently becomes entangled in a series of murders that take place over 25 years. Peasants, thieves, craftsmen, monks, nuns, nobles, and even saints must be investigated and interrogated to expose the truth.', 'https://www.igdb.com/games/pentiment', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.6, 0, 10.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
