VALUES (NULL, NULL, 1906, 'Gone Home', 'Gone Home', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qwhxxrcxzw7inwfrfkbq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar713a.jpg', 'A first-person exploratory game taking place in 1995 in which Katie, a university student back from Europe, arrives at her family''s newly inherited mansion only to find nobody there, with a note from her younger sister Sam suggesting that she''s left home. Katie must explore the mansion to put together the stories of where her parents have gone and why Sam has decided to leave.', 'https://www.igdb.com/games/gone-home', '["Linux", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.4, 0, 10.52, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
