VALUES (NULL, NULL, 8260, 'King''s Quest', 'King''s Quest', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1s8v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrs9.jpg', 'King’s Quest is a collection of five different chapter releases, each focusing on an untold tale in Graham’s past. In each chapter, an aging King Graham reflects on his life of adventure with his granddaughter, Gwendolyn, while players are transported back to influence first-hand the decisions and events that shaped a kingdom. Embark on an extraordinary journey across the world of Daventry.', 'https://www.igdb.com/games/kings-quest', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.6, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
