VALUES (NULL, NULL, 279123, 'Momento', 'Momento', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc5a8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6f25.jpg', 'Momento is a cozy room decorator with a twist: the choices you make play out over the course of a lifetime! Decorate your room, choose which items are important to you, and discover how the objects you choose will alter the course of the story, in a winding ode to the power of everyday things.', 'https://www.igdb.com/games/momento', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Nintendo Switch"]', NULL, NULL, 0, 7.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
