VALUES (NULL, NULL, 7307, 'Folklore', 'Folklore', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob94f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/i30scdfkn2p4u5bxjsfr.jpg', 'Folklore is a dark fantasy action role-playing game developed by Game Republic and published by Sony Computer Entertainment exclusively for the PlayStation 3.

Set in the mysterious Irish village of Doolin, the story follows two protagonists: Ellen, a young woman searching for answers about her supposedly deceased mother, and Keats, a journalist investigating supernatural phenomena. Their separate investigations lead them into the Netherworld, a realm inhabited by spirits and mythical creatures known as Folks.', 'https://www.igdb.com/games/folklore', '["PlayStation 3"]', NULL, 7.5, 0, 9.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
