VALUES (NULL, NULL, 111474, 'Blade & Sorcery', 'Blade & Sorcery', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zqy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6a8m.jpg', 'Blade & Sorcery is a built-for-VR medieval fantasy sandbox with full physics driven melee, ranged and magic combat. Become a powerful warrior, ranger or sorcerer and devastate your enemies.', 'https://www.igdb.com/games/blade-and-sorcery', '["Oculus VR", "SteamVR", "Oculus Rift"]', NULL, 7.9, 0, 7.52, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
