VALUES (NULL, NULL, 138871, 'The Life and Suffering of Sir Brante', 'The Life and Suffering of Sir Brante', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2i7r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjg3.jpg', 'A narrative-driven RPG set in a gritty world where a person''s Lot is determined at birth, while the gods are real and preside over the fates of men. Set out on a lifelong journey and carve out your own destiny. Will you become a judge, an inquisitor, or conspire against the old order? You decide!', 'https://www.igdb.com/games/the-life-and-suffering-of-sir-brante', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 10.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
