VALUES (NULL, NULL, 14523, 'Helldivers', 'Helldivers', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mo3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4iq.jpg', 'Helldivers is a topdown shooter set in a satirical dystopian future where mankind is ruled by a managed democracy. You are part of the Helldivers – the spearhead of humanity’s defense against the perpetual alien threat on Super Earth.

With up to four player co-op missions, working together as a team is vital, whether calling in strikes or placing weapons, each action must be totally synchronized to achieve the objectives. This isn’t just a four player co-op game; it’s a co-op game that relies on the global efforts of the entire Helldivers community!', 'https://www.igdb.com/games/helldivers', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation Vita"]', NULL, 7.9, 0, 8.51, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
