VALUES (NULL, NULL, 252869, 'Last Train Home', 'Last Train Home', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6lyl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2cn2.jpg', 'The Great War is over - the fight continues. Command a legion of soldiers, desperately trying to make their way home amidst the chaos of civil war. Lead them through the unforgiving wilderness onboard an armored train. Manage your crew and resources and try to survive.', 'https://www.igdb.com/games/last-train-home--1', '["PC (Microsoft Windows)"]', NULL, 7.9, 0, 9.53, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
