VALUES (NULL, NULL, 11119, 'Fallout Shelter', 'Fallout Shelter', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6p4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcqk.jpg', 'Fallout Shelter puts you in control of a state-of-the-art underground Vault from Vault-Tec. Build the perfect Vault, keep your Dwellers happy, and protect them from the dangers of the Wasteland.

Vault-Tec has provided the tools, but the rest is up to you. What are you waiting for? Get started building your Vault today for free.', 'https://www.igdb.com/games/fallout-shelter', '["PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Xbox One", "Nintendo Switch"]', NULL, 6.6, 0, 9.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
