VALUES (NULL, NULL, 86477, 'The Surge 2', 'The Surge 2', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y0k.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5vp.jpg', 'The Surge 2 keeps what fans and critics loved about the original while also expanding greatly upon the formula. The Surge 2 takes place in a brand new environment: a sprawling, devastated city with larger, more ambitious level design and improved engine. Combat is more brutal and tactical than ever, with even more options thanks to an expanded limb targeting system.', 'https://www.igdb.com/games/the-surge-2', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.4, 0, 11.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
