VALUES (NULL, NULL, 36718, 'Tannenberg', 'Tannenberg', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c7p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar609.jpg', 'Tannenberg takes the 1914-1918 WW1 Game Series to the Eastern Front. Warfare on the border of the Russian Empire is a tense battle for survival – can your squad weather the storm of battle?', 'https://www.igdb.com/games/tannenberg', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 6.4, 0, 1.2, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
