VALUES (NULL, NULL, 121531, 'Gamedec', 'Gamedec', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9fwi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar621.jpg', 'Gamedec is an adaptive cyberpunk RPG. As a private detective, it’s your job to solve crimes inside virtual worlds. What decisions will you make in a world where child slavery is a F2P game, where murder over a game-clan dispute is an every-day reality? Who will you become in the XXII century?', 'https://www.igdb.com/games/gamedec', '["PC (Microsoft Windows)", "PlayStation 5", "Nintendo Switch"]', NULL, 7.5, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
