VALUES (NULL, NULL, 3188, 'Murdered: Soul Suspect', 'Murdered: Soul Suspect', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r7a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzxz.jpg', 'Murdered: Soul Suspect is a supernatural detective thriller which challenges players to solve possibly the hardest case of all… their own murder.

Set in Salem Massachusetts, players have the freedom to explore the New England-style wooden houses, narrow streets, Gothic churches and historical landmarks for clues. They will need to battle demonic spirits to preserve their souls whilst uncovering the shocking revelations about who is responsible for their death.', 'https://www.igdb.com/games/murdered-soul-suspect', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 6.3, 0, 1.1, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
