VALUES (NULL, NULL, 166722, 'The Case of the Golden Idol', 'The Case of the Golden Idol', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9tog.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11x6.jpg', 'A new kind of detective game that allows you to think and investigate freely. Discover clues surrounding 12 strange and gruesome deaths and build your own theory. Pick your suspect, deduce the motive, unmask the awful truth.', 'https://www.igdb.com/games/the-case-of-the-golden-idol', '["Xbox Series X|S", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.8, 0, 1.03, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
