VALUES (NULL, NULL, 406712, 'Forensics: Crime Scene Detective', 'Forensics: Crime Scene Detective', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc941.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar635c.jpg', 'Become a forensic specialist in a realistic crime lab simulator. Investigate crime scenes, collect microscopic evidence, and identify perpetrators in the lab using DNA and digital analysis. Based on the experience and insights of experts from the State Criminal Police Office Rhineland-Palatinate.', 'https://www.igdb.com/games/forensics-crime-scene-detective', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 1.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
