VALUES (NULL, NULL, 1348, 'Ghost Trick: Phantom Detective', 'Ghost Trick: Phantom Detective', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/udogb7sozvw0lwefbu1x.jpg', 'Ghost Trick: Phantom Detective is a puzzle/adventure game for the Nintendo DS and iOS. It was developed mainly by Shu Takumi, the man behind the Ace Attorney Series. Game''s story centers on the protagonist Sissel, and his ghost''s struggle to discover who he was when he was alive and who killed him. The player assumes the role of this ghost, who has the ability to perform various Ghost Tricks to solve puzzles and navigate the world around him.', 'https://www.igdb.com/games/ghost-trick-phantom-detective', '["iOS", "Nintendo DS"]', NULL, 7.0, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
