VALUES (NULL, NULL, 127165, 'The Outlast Trials', 'The Outlast Trials', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coce2f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar12vv.jpg', 'The Outlast Trials is a survival horror game you can play by yourself or with other players online. You''ll have to survive the twisted, sadistic and bizarre experiments of the Murkoff Corporation, alone or in a group up to 4 players.', 'https://www.igdb.com/games/the-outlast-trials', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 1.02, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
