VALUES (NULL, NULL, 148372, 'Victoria 3', 'Victoria 3', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4v4h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1tfb.jpg', 'Paradox Development Studio invites you to build your ideal society in the tumult of the exciting and transformative 19th century. Balance the competing interests in your society and earn your place in the sun in Victoria 3, one of the most anticipated games in Paradox’s history.', 'https://www.igdb.com/games/victoria-3', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.7, 0, 1.05, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
