VALUES (NULL, NULL, 1981, 'Saints Row IV', 'Saints Row IV', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nrn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arf5k.jpg', 'Saints Row IV is an open-world action-adventure game with third-person shooter combat and a heavy science fiction and comedy bent. It is the fourth main entry in the Saints Row series and the last of the original storyline. Players freely explore a simulated version of the city of Steelport, taking on story missions and side activities, and gain superpowers such as super speed, high jumps, and elemental attacks that reshape how they move and fight. The player character is highly customizable, and a two-player cooperative mode is supported.', 'https://www.igdb.com/games/saints-row-iv', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 7.9, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
