VALUES (NULL, NULL, 361826, 'Denshattack!', 'Denshattack!', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaawz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar419y.jpg', 'Flip, trick and grind your train in a fast-paced, off-the-rails ride through a colourful Japanese dystopia. Outmatch rival gangs, wreck a shady megacorp, and take back the tracks with nothing but skill, speed, and style.', 'https://www.igdb.com/games/denshattack', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.2, 0, 1.01, '2026-11-28 13:59:23', '2026-11-28 13:59:23')
