VALUES (NULL, NULL, 22778, 'Outward', 'Outward', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1iui.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar57l.jpg', 'Outward is an open world RPG that you play alone or with friends, either online or in splitscreen. It''s more than just an open world RPG you can play coop though: it is an adventurer life simulator. You live the life of an adventurer, from his or her humble beginnings up until retirement. Your life isn''t only about killing monsters and looting: you need to eat, drink and sleep; preparing accordingly before jumping into danger. Everything is meant to feel more real and consequential, while still taking place in a high fantasy universe with magic and exotic creatures.', 'https://www.igdb.com/games/outward', '["Google Stadia", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.8, 0, 18.3625, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
