VALUES (NULL, NULL, 248643, 'Enshrouded', 'Enshrouded', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod12a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6cdr.jpg', 'You are Flameborn, last ember of hope of a dying race. Awaken, survive the terror of a corrupting fog, and reclaim the lost beauty of your kingdom. Venture into a vast world, vanquish punishing bosses, build grand halls and forge your path in this co-op survival Action RPG for up to 16 players.', 'https://www.igdb.com/games/enshrouded', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.4, 0, 1.4362222222222222e+01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
