VALUES (NULL, NULL, 27134, 'Deep Rock Galactic', 'Deep Rock Galactic', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaat4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4nr.jpg', 'Deep Rock Galactic is a cooperative first-person shooter set on the alien planet Hoxxes IV. Players take on the role of dwarven space miners employed by an intergalactic mining corporation, completing missions in procedurally generated cave systems filled with hostile alien wildlife. The game supports up to four players who choose from distinct classes, each with unique weapons and traversal tools that complement each other. Missions involve extracting resources, fighting swarms of enemies, and navigating destructible environments before escaping via drop pod.', 'https://www.igdb.com/games/deep-rock-galactic', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.1, 0, 1.36077777777777786e+01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
