VALUES (NULL, NULL, 27085, 'We Need to Go Deeper', 'We Need to Go Deeper', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24kb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhhm.jpg', 'We Need to Go Deeper is a 2-4-player cooperative submarine rogue-like set in a Jules Verne-inspired undersea universe. In the game, you and your crew must embark on many voyages into a mysterious undersea trench known as The Living Infinite.', 'https://www.igdb.com/games/we-need-to-go-deeper', '["PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, 6.8, 0, 10.01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
