VALUES (NULL, NULL, 21, 'BioShock 2', 'BioShock 2', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mlj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aplsuaqxagpwzy0n935n.jpg', 'BioShock 2 is the second game of the BioShock series and the sequel to BioShock. It continues the grand storyline of the underwater metropolis Rapture. BioShock 2 capitalizes and improves upon the high-quality effects, unique gameplay elements, and immersive atmosphere that defined the first game. It explores more brutal gameplay than its predecessor, with new enemies, weapons, Plasmids, and Gene Tonics.', 'https://www.igdb.com/games/bioshock-2', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 8.4, 0, 6.0175, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
