VALUES (NULL, NULL, 103329, 'Control', 'Control', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2evj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5bz.jpg', 'Control is a third-person action-adventure game set in the Federal Bureau of Control, a secretive U.S. government agency that studies paranormal phenomena. Players control Jesse Faden, who arrives at the Bureau''s headquarters, the Oldest House, to find it invaded by a hostile force called the Hiss. Gameplay combines supernatural abilities with a shape-shifting firearm, and the environment is reactive and destructible.', 'https://www.igdb.com/games/control', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.3, 0, 1.42800000000000011e+01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
