VALUES (NULL, NULL, 142076, 'Cruelty Squad', 'Cruelty Squad', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hn0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11ss.jpg', 'Cruelty Squad is a tactical first person shooter set in the hardcore gig economy of corporate liquidations. You''re an emotionally dead combat-substance fueled grunt of Cruelty Squad, a depraved subsidiary company tasked with performing wetworks for its host conglomerate. Will you make the Corporate Arch Demoness proud or succumb to bitter tears of failure?', 'https://www.igdb.com/games/cruelty-squad', '["PC (Microsoft Windows)"]', NULL, 8.6, 0, 8.73, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
