VALUES (NULL, NULL, 325594, 'Split Fiction', 'Split Fiction', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95gf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3me6.jpg', 'Split Fiction is a 2025 cooperative multiplayer game. It follows two writers, Mio Hudson and Zoe Foster, as they become trapped in their imaginations.', 'https://www.igdb.com/games/split-fiction', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.0, 0, 10.5625, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
