VALUES (NULL, NULL, 135243, 'It Takes Two', 'It Takes Two', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob22v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4mc7.jpg', 'It Takes Two is a cooperative action-adventure game designed exclusively for two players, playable in local split-screen or online. Players control Cody and May, a married couple transformed into dolls, as they travel through fantastical environments based on their home and relationship. Gameplay combines platforming, puzzle-solving, and action sequences, with each level introducing new mechanics and giving the two characters different abilities that must be used together to progress. The game frequently changes its core mechanics from chapter to chapter, incorporating sections involving shooting, racing, flight, and other genres.', 'https://www.igdb.com/games/it-takes-two', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.9, 0, 7.61666666666666625e+00, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
