VALUES (NULL, NULL, 203258, 'Warhammer 40,000: Boltgun', 'Warhammer 40,000: Boltgun', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6j5y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1nt6.jpg', 'Load up your Boltgun and unleash the awesome Space Marine arsenal to blast your way through an explosion of sprites, pixels and blood in a perfect blend of Warhammer 40,000, frenetic gameplay and the stylish visuals of 90’s retro shooters.', 'https://www.igdb.com/games/warhammer-40000-boltgun', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 2.015, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
