VALUES (NULL, NULL, 228175, 'Starship Troopers: Extermination', 'Starship Troopers: Extermination', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bw3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar24jr.jpg', 'Starship Troopers: Extermination drops up to 16 players right into the fight against the Bug menace in this co-op first person shooter. Suit up and ship out to a far-off front as a Trooper in the Deep Space Vanguard, an elite Special Forces group within the Mobile Infantry. It’s up to squads like yours to battle against hundreds of bloodthirsty insectoid aliens and take back fallen colonies for the Federation. The only good Bug is a dead Bug!', 'https://www.igdb.com/games/starship-troopers-extermination', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.7, 0, 8.72333333333333449e+00, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
