VALUES (NULL, NULL, 3189, 'Project Zomboid', 'Project Zomboid', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7kod.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3w0k.jpg', 'Project Zomboid is the ultimate in zombie survival. Alone or in MP: you loot, build, craft, fight, farm and fish in a struggle to survive. A hardcore RPG skillset, a vast map, a massively customisable sandbox and a cute tutorial raccoon await the unwary. So how will you die?', 'https://www.igdb.com/games/project-zomboid', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.2, 0, 1.63514285714285705e+01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
