VALUES (NULL, NULL, 126290, 'Far Cry 6', 'Far Cry 6', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2npg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar165y.jpg', 'Dive into the gritty world of a modern-day guerrilla revolution to liberate a nation from its oppressive dictators. Welcome to Yara, a tropical paradise frozen in time. Far Cry 6 thrusts players into a modern-day guerrilla revolution. As dictator of Yara, Anton Castillo is intent on restoring his nation back to its former glory by any means, with his son, Diego, following in his bloody footsteps. Become a guerrilla fighter and liberate Yara.', 'https://www.igdb.com/games/far-cry-6', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.5, 0, 5.69666666666666632e+00, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
