VALUES (NULL, NULL, 112875, 'God of War Ragnarök', 'God of War Ragnarök', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coba3d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tqf.jpg', 'God of War: Ragnarök is the ninth installment in the God of War series and the sequel to 2018''s God of War. Continuing with the Norse mythology theme, the game is set in ancient Norway and features series protagonists Kratos, the former Greek God of War, and his young son Atreus. The game kicked off the events of Ragnarök, where Kratos and Atreus must journey to each of the Nine Realms in search of answers as they prepare for the prophesied battle that will end the world.', 'https://www.igdb.com/games/god-of-war-ragnarok', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.3, 0, 3.02, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
