VALUES (NULL, NULL, 493, 'Heavy Rain', 'Heavy Rain', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaajv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/d9rrit0hjrhm6vltstfs.jpg', 'Heavy Rain is a cinematic psychological thriller from game developer Quantic Dream exclusively for the PlayStation 3. Dealing with a range of adult themes, the game revolves around a sophisticated plot and strong narrative threads that explore a complex moral proposition. You assume the role of multiple characters with very different backgrounds, motivations, and skills in a world where each player decision affects what will follow.', 'https://www.igdb.com/games/heavy-rain', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)"]', NULL, 8.1, 0, 2.025, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
