VALUES (NULL, NULL, 1342, 'Beyond: Two Souls', 'Beyond: Two Souls', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8r4w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sbwzrxhxbuyptvn6slvt.jpg', 'A unique psychological action thriller delivered by A-list Hollywood performances by Elliot Page and Willem Dafoe, Beyond: Two Souls takes you on a thrilling journey across the globe as you play out the remarkable life of Jodie Holmes.', 'https://www.igdb.com/games/beyond-two-souls', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.01, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
