VALUES (NULL, NULL, 12520, 'Lovers in a Dangerous Spacetime', 'Lovers in a Dangerous Spacetime', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2543.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcii.jpg', 'Lovers in a Dangerous Spacetime is a frantic 1- or 4-player couch co-op action space shooter set in a massive neon battleship. Only through teamwork can you triumph over the evil forces of Anti-Love, rescue kidnapped space-bunnies, and avoid a vacuumy demise. Deep space is a dangerous place, but you don’t have to face it alone!', 'https://www.igdb.com/games/lovers-in-a-dangerous-spacetime', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.8, 0, 6.76500000000000056e+00, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
