VALUES (NULL, NULL, 130421, 'Jump Space', 'Jump Space', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa8fd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2v6s.jpg', 'Jump Space is a mission based co-op FPS for up to 4 players, where you are the crew of a spaceship. Transition seamlessly from crewing the ship to on-foot exploration and space walks. Engage in intense battles both on the ground and in space, and always keep your ship upgraded and intact.', 'https://www.igdb.com/games/jump-space', '["Xbox Series X|S", "PC (Microsoft Windows)"]', NULL, NULL, 0, 8.5699999999999985e+00, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
