VALUES (NULL, NULL, 29667, 'Trailmakers', 'Trailmakers', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8u8s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar65h6.jpg', 'In the toughest motoring expedition in the universe, you and your friends will build your own vehicles to cross a dangerous wasteland. Explore, crash horribly, use your wits to build a better rig, and get as far as you can with whatever spare parts you find on your way.', 'https://www.igdb.com/games/trailmakers', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.4, 0, 5.04, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
