VALUES (NULL, NULL, 356552, 'Clive Barker''s Hellraiser: Revival', 'Clive Barker''s Hellraiser: Revival', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa5o9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar42el.jpg', 'Experience a new chapter in the legendary horror series like never before. Clive Barker''s Hellraiser: Revival takes first-person action horror survival to the next level. Wield the powers of the Genesis Configuration puzzle box to survive your bargain with the infamous Pinhead.', 'https://www.igdb.com/games/clive-barkers-hellraiser-revival', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.1, 0, 2.025, '2026-11-19 20:56:22', '2026-11-28 13:59:23')
