VALUES (NULL, NULL, 158603, 'Isonzo', 'Isonzo', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4496.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxjq.jpg', 'Ferocious Alpine warfare will test your tactical skills in this authentic WW1 FPS. Battle among the scenic peaks, rugged valleys and idyllic towns of northern Italy. The Great War on the Italian Front is brought to life and elevated to unexpected heights!', 'https://www.igdb.com/games/isonzo', '["Xbox Series X|S", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 7.1, 0, 6.605, '2026-11-20 01:06:03', '2026-11-28 13:59:23')
