VALUES (NULL, NULL, 509, 'Rage', 'Rage', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ybv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/r3tgtzbvocl6oyueucw4.jpg', 'Rage is a first-person shooter set in the not-too-distant future after an asteroid impacts Earth, leaving a ravaged world behind. You emerge into this vast wasteland to discover humanity working to rebuild itself against such forces as raider gangs, mutants, and the Authority – an oppressive government regime that has a special interest in you in particular.', 'https://www.igdb.com/games/rage', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 7.7, 0, 8.19333333333333335e+00, '2026-11-20 22:18:41', '2026-11-28 13:59:23')
