VALUES (NULL, NULL, 14, 'Fallout 2', 'Fallout 2', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ado.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar18xr.jpg', 'A turn-based tactical Western RPG in which the Chosen One is tasked with exploring post-nuclear California to locate and retrieve the fabled Garden of Eden Creation Kit for their famine-stricken tribe, while coming into contact through branching dialogue trees with numerous tribes, factions and micro-civilizations, each with their own virtues, vices, socioeconomic situations and political agendas.', 'https://www.igdb.com/games/fallout-2', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.9, 0, 9.8, '2026-11-20 22:18:41', '2026-11-28 13:59:23')
