VALUES (NULL, NULL, 244, 'The Bureau: XCOM Declassified', 'The Bureau: XCOM Declassified', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28g8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8fp.jpg', 'The year is 1962 and the Cold War has the nation gripped by fear. A top-secret government unit called The Bureau begins investigating a series of mysterious attacks by an enemy more powerful than communism. As agent Carter, call the shots, pull the trigger and lead your squad in a gripping third-person tactical shooter set within a covert war to protect humanity from an otherworldly enemy.', 'https://www.igdb.com/games/the-bureau-xcom-declassified', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 6.4, 0, 7.84333333333333282e+00, '2026-11-21 13:07:40', '2026-11-28 13:59:23')
