VALUES (NULL, NULL, 103244, 'Signalis', 'Signalis', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co62ig.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arga5.jpg', 'Signalis is a classic survival horror experience with a unique aesthetic, full of melancholic mystery. Investigate a dark secret, solve puzzles, fight off nightmarish creatures and navigate dystopian, surreal retrotech worlds as Elster, a technician Replika searching for her lost dreams.', 'https://www.igdb.com/games/signalis', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 1.03566666666666673e+01, '2026-11-21 13:07:40', '2026-11-28 13:59:23')
