VALUES (NULL, NULL, 7599, 'Life Is Strange', 'Life Is Strange', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r8e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pn2wkho1un4rxpsczqxz.jpg', 'Life Is Strange is a five part episodic game that sets out to revolutionize story based choice and consequence games by allowing the player to rewind time and affect the past, present and future.', 'https://www.igdb.com/games/life-is-strange', '["PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox 360", "Xbox One"]', NULL, 8.1, 0, 11.448, '2026-11-21 13:07:40', '2026-11-28 13:59:23')
