VALUES (NULL, NULL, 19441, 'Watch Dogs 2', 'Watch Dogs 2', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2p3j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4w0.jpg', 'Explore a massive and dynamic open world offering an incredible variety of gameplay possibilities. Hack your way through traffic while you engage in dangerous car chases through the winding streets of San Francisco, traverse the rooftops of the colorful and vibrant neighborhoods of Oakland, and infiltrate the cutting-edge offices of Silicon Valley companies. There are many secrets to uncover in the birthplace of the tech revolution.', 'https://www.igdb.com/games/watch-dogs-2', '["Google Stadia", "PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.9, 0, 9.07666666666666621e+00, '2026-11-21 21:29:28', '2026-11-28 13:59:23')
