VALUES (NULL, NULL, 136625, 'Hogwarts Legacy', 'Hogwarts Legacy', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaav6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar79n.jpg', 'Hogwarts Legacy is an immersive, open-world action RPG set in the world first introduced in the Harry Potter books. Now you can take control of the action and be at the center of your own adventure in the wizarding world. Embark on a journey through familiar and new locations as you explore and discover fantastic beasts, customize your character and craft potions, master spell casting, upgrade talents, and become the wizard you want to be. Discover the feeling of living at Hogwarts as you make allies, battle Dark wizards, and ultimately decide the fate of the wizarding world. Your legacy is what you make of it.', 'https://www.igdb.com/games/hogwarts-legacy', '["Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.2, 0, 5.02, '2026-11-21 21:29:28', '2026-11-28 13:59:23')
