VALUES (NULL, NULL, 80, 'The Witcher', 'The Witcher', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xrx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar69xy.jpg', 'Based on the novel series by Andrzej Sapkowski, The Witcher follows Geralt of Rivia, an amnesiac witcher (problem solver and slayer of monsters) whose home, the Kaer Morhen citadel, is besieged by an organization called the Salamandra, who steal their valuable potions and get away. Throughout the game, Geralt must resolve people''s moral dilemmas, connect the dots of his past and track down the Salamandra.', 'https://www.igdb.com/games/the-witcher', '["PC (Microsoft Windows)", "Mac"]', NULL, 8.5, 0, 9.775, '2026-11-21 21:29:28', '2026-11-28 13:59:23')
