VALUES (NULL, NULL, 31712, 'Scum', 'Scum', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa05f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ttv.jpg', 'Scum aims to evolve the multiplayer open world survival game with unprecedented levels of character customization, control and progression, where knowledge and skills are the ultimate weapons for long-term survival. Combining the methodical planning and management of hardcore survival with optional PvP ‘network events’ available to everyone at anytime, SCUM strikes a unique balance between complex simulation and intense action in the next generation of survival game.', 'https://www.igdb.com/games/scum', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 2.015, '2026-11-21 21:29:28', '2026-11-28 13:59:23')
