VALUES (NULL, NULL, 72767, 'Jagged Alliance 3', 'Jagged Alliance 3', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qu5.jpg', 'The country of Grand Chien is thrown into chaos when the elected president goes missing and the paramilitary force known as "the Legion" seizes control. Hire mercenaries, meet interesting characters, and fight in tactically deep turn-based combat in this true successor to a beloved franchise.', 'https://www.igdb.com/games/jagged-alliance-3', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.3, 0, 10.7625, '2026-11-21 21:29:28', '2026-11-28 13:59:23')
