VALUES (NULL, NULL, 4843, 'Kingdom Come: Deliverance', 'Kingdom Come: Deliverance', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4aqi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5m6.jpg', 'Story-driven open-world RPG that immerses you in an epic adventure in the Holy Roman Empire. Avenge your parents'' death as you battle invading forces, go on game-changing quests, and make influential choices. Explore castles, forests, villages and other realistic settings in medieval Bohemia!', 'https://www.igdb.com/games/kingdom-come-deliverance', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 7.6, 0, 1.5372727272727273e+01, '2026-11-22 03:06:26', '2026-11-28 13:59:23')
