VALUES (NULL, NULL, 148228, 'V Rising', 'V Rising', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coby9v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6gbl.jpg', 'Awaken as a vampire. Hunt for blood in nearby settlements to regain your strength and evade the scorching sun to survive. Raise your castle and thrive in an ever-changing open world full of mystery. Gain allies online and conquer the land of the living.', 'https://www.igdb.com/games/v-rising', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.0, 0, 11.3, '2026-11-22 03:06:26', '2026-11-28 13:59:23')
