VALUES (NULL, NULL, 119342, 'Chivalry 2', 'Chivalry 2', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yqh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5r9.jpg', 'Chivalry 2 is a multiplayer first person slasher inspired by epic medieval movie battles. Players are thrust into the action of every iconic moment of the era - from clashing swords, to storms of flaming arrows, to sprawling castle sieges and more.', 'https://www.igdb.com/games/chivalry-2', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.3, 0, 1.31283333333333338e+01, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
