VALUES (NULL, NULL, 596, 'American Conquest', 'American Conquest', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5nr7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark0s.jpg', 'American Conquest: In the year 1492, travel to America as Christopher Columbus and ignite the fire that will fan 300 years of heated battles for land, riches, and freedom. In eight historical campaigns spanning 42 missions, you will take on the roles of great legends such as Francisco Pizarro and George Washington. Secure new technologies, unique weaponry, and improved fighting units, but also master the delicate world of diplomacy. Play with fire! Conquer America.', 'https://www.igdb.com/games/american-conquest', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 6.01500000000000056e+00, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
