VALUES (NULL, NULL, 124954, 'Crusader Kings III', 'Crusader Kings III', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocleh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6dg6.jpg', 'Crusader Kings III is the newest generation in the medieval role-playing grand strategy game series Crusader Kings. Expand and improve your realm, whether a mighty kingdom or modest county. Use marriage, diplomacy and war to increase your power and prestige in a meticulously detailed map that stretches from Spain to India, Scandinavia to Central Africa.', 'https://www.igdb.com/games/crusader-kings-iii', '["Xbox Series X|S", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 8.7, 0, 6.47199999999999953e+00, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
