VALUES (NULL, NULL, 3084, 'Cry of Fear', 'Cry of Fear', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6m51.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rpiagrelhhscy3i6nihb.jpg', 'Cry of Fear is a single-player, horror modification for Half-Life 1 that brings you all the horrors you have always been afraid of.
This is a free total converstion of Half-Life 1, which means none of the assets from Half-Life 1 have been used in this mod or any files from other people, it is a totally unique experience. Everything is made exclusively by Team Psykskallar, the Cry of Fear developers.', 'https://www.igdb.com/games/cry-of-fear', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 2.05, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
