VALUES (NULL, NULL, 222341, 'Silent Hill 2', 'Silent Hill 2', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavaf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ys1.jpg', 'Silent Hill 2 Remake is a ground-up reimagining of the 2001 psychological horror game. It follows James Sunderland as he searches for his deceased wife in the fog-shrouded town of Silent Hill. The remake features entirely rebuilt visuals in Unreal Engine 5, over-the-shoulder gameplay, reworked combat, and new voice acting.', 'https://www.igdb.com/games/silent-hill-2--1', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.9, 0, 2.03, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
