VALUES (NULL, NULL, 222342, 'Silent Hill: Townfall', 'Silent Hill: Townfall', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc5sw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6gdw.jpg', 'Silent Hill: Townfall is a full-length, self-contained psychological horror set against the cold, isolated backdrop of Scotland, 1996.

Players can explore St. Amelia, where fog-soaked streets, abandoned communities, and forgotten corners tell their story through atmosphere and history. Reality and delusion subtly intertwine, luring players into the depths of St. Amelia''s grounded, tangible world.', 'https://www.igdb.com/games/silent-hill-townfall', '["PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.8, 0, 3.03, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
