VALUES (NULL, NULL, 143482, 'Six Days in Fallujah', 'Six Days in Fallujah', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91ba.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2ddm.jpg', 'Six Days in Fallujah is a first-person tactical military shooter that recreates true stories of Marines, Soldiers, and Iraqi civilians who fought Al Qaeda during the toughest urban battle since 1968.', 'https://www.igdb.com/games/six-days-in-fallujah--1', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 6.76500000000000056e+00, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
