VALUES (NULL, NULL, 2058, 'Payday 2', 'Payday 2', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaaqu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6emt.jpg', 'Payday 2 is an action-packed, four-player co-op shooter that once again lets gamers don the masks of the original crew: Dallas, Hoxton, Wolf and Chains as they descend on Washington D.C. for an epic crime spree.', 'https://www.igdb.com/games/payday-2', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, 7.4, 0, 11.93, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
