VALUES (NULL, NULL, 127350, 'Weird West', 'Weird West', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4no1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar11dd.jpg', 'Discover a dark fantasy reimagining of the Wild West where lawmen and gunslingers share the frontier with fantastical creatures. Journey through the origin stories of a group of atypical heroes, written into legend by the decisions you make in an unforgiving land. Each journey is unique and tailored to the actions taken - a series of high stakes stories where everything counts and the world reacts to the choices you make. Form a posse or venture forth alone into an otherworldly confines of the Weird West and make each legend your own.', 'https://www.igdb.com/games/weird-west', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.9, 0, 9.18666666666666742e+00, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
