VALUES (NULL, NULL, 832, 'Planescape: Torment', 'Planescape: Torment', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ggb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru99.jpg', 'A CRPG set in the Dungeons & Dragons setting of Planescape in which The Nameless One, an immortal amnesiac, sets off on a quest across the infinite Planes and gathers a party of conflicted companions to find out who he is and reclaim his mortality. Throughout it, he faces the consequences of the horrors he committed in his past lives and tries to find the root of all the torment plaguing his companions and the Planes.', 'https://www.igdb.com/games/planescape-torment', '["Linux", "PC (Microsoft Windows)", "iOS", "Mac"]', NULL, 7.9, 0, 10.8025, '2026-11-24 04:24:23', '2026-11-28 13:59:23')
