VALUES (NULL, NULL, 101461, 'Green Hell', 'Green Hell', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9d3h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ara9b.jpg', 'Green Hell is a sweltering struggle for survival in the Amazonian rainforest. Clinging to life, the player is set on a journey of durability as the effects of solitude wear heavy not only on the body but also the mind. How long can you survive against the dangers of the unknown?', 'https://www.igdb.com/games/green-hell', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 10.66, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
