VALUES (NULL, NULL, 121998, 'Medieval Dynasty', 'Medieval Dynasty', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobyff.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcp4.jpg', 'Hunt, survive, build and lead in the harsh Middle Ages: Create your own Medieval Dynasty and ensure its long-lasting prosperity or die trying! Play alone or team up with friends to enjoy the ultimate medieval experience.', 'https://www.igdb.com/games/medieval-dynasty', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 6.9, 0, 6.265, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
