VALUES (NULL, NULL, 199677, 'Total Conflict: Resistance', 'Total Conflict: Resistance', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9qfl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1m9t.jpg', 'Total Conflict: Resistance is a unique symbiosis of global strategy, tactics and first-person action. Realistic mass battles, many types of armored vehicles, weapons, uniforms, unique mechanics, immersive free gameplay. Lead any state and bring it to greatness!', 'https://www.igdb.com/games/total-conflict-resistance', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.69999999999999929e+00, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
