VALUES (NULL, NULL, 1886, 'Homefront: The Revolution', 'Homefront: The Revolution', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ksh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardtj.jpg', 'Homefront: The Revolution is an open-world first person shooter where you must lead the Resistance movement in guerrilla warfare against a superior military force.A living, breathing, open world responds to your actions - you and your Resistance Cell can inspire a rebellion on the streets and turn Occupation into Revolution, as oppressed civilians take up the fight.', 'https://www.igdb.com/games/homefront-the-revolution', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 5.6, 0, 5.76, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
