VALUES (NULL, NULL, 27421, 'Middle-earth: Shadow of War', 'Middle-earth: Shadow of War', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20pq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/x6dqi0ysi0prnfiwypyt.jpg', 'Go behind enemy lines to forge your army, conquer Fortresses and dominate Mordor from within. Experience how the award winning Nemesis System creates unique personal stories with every enemy and follower, and confront the full power of the Dark Lord Sauron and his Ringwraiths in this epic new story of Middle-earth.', 'https://www.igdb.com/games/middle-earth-shadow-of-war', '["PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "Xbox One"]', NULL, 8.2, 0, 1.29783333333333352e+01, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
