VALUES (NULL, NULL, 148781, 'Motor Town: Behind the Wheel', 'Motor Town: Behind the Wheel', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ped.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkaj.jpg', 'Enjoy realistic driving in the open world. Relaxing cargo deliveries or driving buses and taxes will give you enough money to buy new cars and parts. You can test your driving skills at the race track. It''s all about pure driving pleasure!', 'https://www.igdb.com/games/motor-town-behind-the-wheel', '["PC (Microsoft Windows)"]', NULL, 7.1, 0, 10.26, '2026-11-26 02:21:07', '2026-11-28 13:59:23')
