VALUES (NULL, NULL, 347668, 'Resident Evil Requiem', 'Resident Evil Requiem', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobmj0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4v90.jpg', 'Resident Evil Requiem is the ninth entry in the Resident Evil series. Experience terrifying survival horror with FBI analyst Grace Ashcroft, and dive into pulse-pounding action with legendary agent Leon S. Kennedy. Both of their journeys and unique gameplay styles intertwine into a heart-stopping, emotional experience that will chill you to your core.', 'https://www.igdb.com/games/resident-evil-requiem', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.0, 0, 10.625, '2026-11-26 23:52:17', '2026-11-28 13:59:23')
