VALUES (NULL, NULL, 36646, 'GTFO', 'GTFO', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4cnq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcp3.jpg', 'GTFO is a 4 player action/horror cooperative game for those looking for a real challenge. Players get to play as a team of scavengers, forced to explore and extract valuable artifacts from a vast underground complex that has been overrun by horrifying monsters. Gather weapons, tools and resources to help you survive - and work to unearth the answers about your past and how to escape.', 'https://www.igdb.com/games/gtfo', '["PC (Microsoft Windows)"]', NULL, 7.7, 0, 11.43, '2026-11-26 23:52:17', '2026-11-28 13:59:23')
