VALUES (NULL, NULL, 103320, 'The Forgotten City', 'The Forgotten City', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3muu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aremu.jpg', 'The Forgotten City is a mystery adventure game of exploration and deduction, and a re-imagining of the critically acclaimed mod of the same name. Combat is an option, but violence will only get you so far. Only by questioning an intertwined community of colorful characters, cleverly exploiting the time loop, and making difficult moral choices can you hope to solve this epic mystery. Here, your decisions matter. The fate of the city is in your hands.', 'https://www.igdb.com/games/the-forgotten-city', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.5, 0, 6.02333333333333342e+00, '2026-11-26 23:52:17', '2026-11-28 13:59:23')
