VALUES (NULL, NULL, 891, 'Team Fortress 2', 'Team Fortress 2', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6rzl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arf06.jpg', 'One of the most popular online action games of all time, Team Fortress 2 delivers constant free updates—new game modes, maps, equipment and, most importantly, hats. Nine distinct classes provide a broad range of tactical abilities and personalities, and lend themselves to a variety of player skills.', 'https://www.igdb.com/games/team-fortress-2', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 8.1, 0, 11.15, '2026-11-26 23:52:17', '2026-11-28 13:59:23')
