VALUES (NULL, NULL, 127816, 'Paradise Killer', 'Paradise Killer', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9910.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc55.jpg', 'Paradise Island, a world outside reality. There’s been a murder that only "investigation freak" Lady Love Dies can solve. Gather evidence and interrogate suspects in this open world adventure. You can accuse anyone, but you’ll have to prove your case in trial to convict. It’s up to you to decide who’s guilty.', 'https://www.igdb.com/games/paradise-killer', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 8.3, 0, 6.51500000000000056e+00, '2026-11-27 20:45:57', '2026-11-28 13:59:23')
