VALUES (NULL, NULL, 123861, 'Songs of Syx', 'Songs of Syx', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaomk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arud7.jpg', 'As a king in the world of Syx, you lead your people from small colonies to prosperous mega-cities and empires. You manage everything from individual subject''s needs to global diplomacy, trade and a scheming nobility that might try to usurp you from time to time.', 'https://www.igdb.com/games/songs-of-syx', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 7.8, 0, 6.82, '2026-11-28 04:52:47', '2026-11-28 13:59:23')
