VALUES (NULL, NULL, 149853, 'Space Station 14', 'Space Station 14', 'game', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocmxi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6dve.jpg', 'Disasters, enemies, and incompetence conspire to make each shift aboard the station a unique and hellish experience. Sign up today to explore intricate game mechanics and enjoy limitless player interaction! (Nanotrasen Inc. is not responsible for injury, death, or worse).', 'https://www.igdb.com/games/space-station-14', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 10.01, '2026-11-28 04:52:47', '2026-11-28 13:59:23')
